create table genai_project (
    id         number,
    name       varchar2(4000 byte),
    query      clob,
    task       varchar2(4000 byte),
    task_rules varchar2(4000 byte)
);

alter table genai_project
    add constraint genai_project_pk primary key ( id )
        using index enable;


